_STOP = threading.Event()


def configuration():
    required = ('BOT_TOKEN', 'OWNER_TELEGRAM_ID', 'TURSO_DATABASE_URL', 'TURSO_AUTH_TOKEN')
    values = {name: os.environ.get(name, '').strip() for name in required}
    missing = [name for name, value in values.items() if not value]
    if missing:
        raise ValueError('Заполните переменные Render: ' + ', '.join(missing))
    if not re.fullmatch(r'[1-9][0-9]{4,19}', values['OWNER_TELEGRAM_ID']):
        raise ValueError('OWNER_TELEGRAM_ID должен быть числовым Telegram ID владельца.')
    if not values['TURSO_DATABASE_URL'].startswith(('libsql://', 'https://')):
        raise ValueError('TURSO_DATABASE_URL должен начинаться с libsql:// или https://.')
    if not shutil.which('node'):
        raise ValueError('Не найден Node.js. Проверьте Build Command в настройках Render.')
    url = (os.environ.get('APP_URL') or os.environ.get('RENDER_EXTERNAL_URL') or '').strip().rstrip('/')
    if url:
        parsed = parse.urlparse(url)
        if parsed.scheme != 'https' or not parsed.hostname or parsed.username or parsed.password:
            raise ValueError('APP_URL должен быть публичным HTTPS-адресом сайта.')
    return values, url


def telegram_call(token, method, data, timeout=35):
    body = json.dumps(data, ensure_ascii=False).encode('utf-8')
    req = request.Request('https://api.telegram.org/bot' + token + '/' + method,
                          data=body, headers={'Content-Type': 'application/json'}, method='POST')
    with request.urlopen(req, timeout=timeout) as response:
        result = json.load(response)
    if not result.get('ok'):
        raise RuntimeError('Telegram API error ' + str(result.get('error_code', 'unknown')))
    return result.get('result')


def start_message(token, chat_id, app_url):
    if app_url:
        data = {'chat_id': chat_id,
                'text': 'Добро пожаловать в WOOD TABLES. Открой игру и присоединяйся к столу.',
                'reply_markup': {'inline_keyboard': [[{'text': 'Открыть игру',
                                                       'web_app': {'url': app_url + '/'}}]]}}
    else:
        data = {'chat_id': chat_id, 'text': 'Сайт запускается. Укажите HTTPS-адрес в APP_URL.'}
    telegram_call(token, 'sendMessage', data, timeout=15)


def polling(token, app_url):
    offset = None
    while not _STOP.is_set():
        try:
            params = {'timeout': 25, 'allowed_updates': ['message']}
            if offset is not None:
                params['offset'] = offset
            updates = telegram_call(token, 'getUpdates', params, timeout=35) or []
            for update in updates:
                offset = max(offset or 0, int(update.get('update_id', 0)) + 1)
                msg = update.get('message') or {}
                chat = msg.get('chat') or {}
                words = str(msg.get('text') or '').split(maxsplit=1)
                command = words[0].split('@', 1)[0].lower() if words else ''
                if command == '/start' and chat.get('type') == 'private' and chat.get('id') is not None:
                    try:
                        start_message(token, chat['id'], app_url)
                    except Exception:
                        print('Telegram: не удалось ответить на /start.', flush=True)
        except error.HTTPError as exc:
            if exc.code == 409:
                print('Telegram: конфликт получения сообщений. Проверьте webhook и другие запущенные копии бота.', flush=True)
            elif exc.code == 401:
                print('Telegram: BOT_TOKEN не принят. Проверьте токен в Render.', flush=True)
            else:
                print('Telegram: ошибка связи, повторная попытка.', flush=True)
            _STOP.wait(10)
        except Exception:
            if not _STOP.is_set():
                print('Telegram: соединение временно недоступно, повторная попытка.', flush=True)
                _STOP.wait(5)


def main():
    try:
        config, app_url = configuration()
    except ValueError as exc:
        print(str(exc), file=sys.stderr, flush=True)
        return 1
    if not app_url:
        print('Вне Render укажите публичный HTTPS-адрес сайта в APP_URL.', flush=True)
    base = Path(__file__).resolve().parent
    node = shutil.which('node')
    proc = None
    with tempfile.TemporaryDirectory(prefix='.wood-run-', dir=base) as folder:
        directory = Path(folder)
        (directory / 'worker.mjs').write_bytes(gzip.decompress(base64.b64decode(_SITE_GZIP)))
        (directory / 'server.mjs').write_text(_SERVER, encoding='utf-8')
        try:
            proc = subprocess.Popen([node, str(directory / 'server.mjs')], cwd=str(base))
        except OSError:
            print('Не удалось запустить веб-сервер. Проверьте Build Command.', file=sys.stderr, flush=True)
            return 1
        thread = threading.Thread(target=polling, args=(config['BOT_TOKEN'], app_url), daemon=True)
        thread.start()
        def shutdown(_signum, _frame):
            _STOP.set()
            if proc.poll() is None:
                proc.terminate()
        signal.signal(signal.SIGTERM, shutdown)
        signal.signal(signal.SIGINT, shutdown)
        try:
            while proc.poll() is None and not _STOP.wait(0.5):
                pass
        finally:
            _STOP.set()
            if proc.poll() is None:
                proc.terminate()
                try:
                    proc.wait(timeout=5)
                except subprocess.TimeoutExpired:
                    proc.kill()
                    proc.wait()
    return proc.returncode if proc.returncode is not None and proc.returncode > 0 else 0


if __name__ == '__main__':
    raise SystemExit(main())
